INSERT INTO skills_activity VALUES(1,'Préparation du sol','Préparer le sol : amender le sol, fertiliser (apporter du compost, du fumier, des engrais), ameublir le sol, le couvrir d''un mulch.',2);
INSERT INTO skills_activity VALUES(2,'Plantation','Préparer le trou de plantation, dépoter la plante, couper les racines excédentaires, planter dans le trou, tasser la terre, arroser...',2);
INSERT INTO skills_activity VALUES(3,'Tailler les rosiers','Couper le bois mort, Couper le branchages pas harmonieux, voire couper au pied pour régénérer la plante.',2);
INSERT INTO skills_activity VALUES(4,'Programmation Python','Assistance à la programmation en Python',1);
INSERT INTO skills_activity VALUES(5,'Administration de poste','Mettre à jour, créer un nouveau compte, installer un logiciel en tant qu''administrateur.',1);
INSERT INTO skills_activity VALUES(6,'Dépannage informatique','Diagnostique de l''ordinateur : mise à jour, sécurité, sauvegarde, évaluer l''encombrement du disque dur, de la ram et l''âge du matériel',1);
INSERT INTO skills_activity VALUES(7,'Faire un fiche de synthèse du personnage','Lister les caractéristiques du personnage : ses désirs, son histoire, ses traits marquants...pour préparer la prise de rôle.',4);
INSERT INTO skills_activity VALUES(8,'Répéter le rôle','Activité autour de la répétition du rôle',4);
INSERT INTO skills_activity VALUES(9,'construire CV','Lister les expériences, les formations, les compétences adapter au projet professionnel visé.',3);
INSERT INTO skills_activity VALUES(10,'Rédiger une lettre de motivation','Illustrer avec des éléments factuels pourquoi le candidat est adapté au poste visé.',3);
INSERT INTO skills_activity VALUES(11,'ciblage d''entreprises','rechercher des entreprises par rapport à  la proximité géographique, le type de poste, la taille de l''entreprise, sa capacité d''embauche.',3);
INSERT INTO skills_activity VALUES(12,'Préparer entretien','Entretien de simulation, préparer les questions les plus fréquentes. préparer le pitch. Ce que le candidat peut apporter à  l''entreprise.',3);
INSERT INTO skills_skill VALUES(1,'informatique','Compétence lié d''avantage à l''utilisation et la configuration d''un ordinateur d''avantage qu''à la science du traitement de l''information.');
INSERT INTO skills_skill VALUES(2,'Jardinage','Activité indispensable à la production de légume et de fruits pour l''alimentation humaine. Cette activité de pousse de plante peut être aussi liés à des productions non comestibles pour l''agrément ou la fourniture de matériaux.');
INSERT INTO skills_skill VALUES(3,'Recherche d''emploi','Activité lié à trouver un emploi ou chercher un autre emploi plus en rapport avec un nouveau projet professionnel');
INSERT INTO skills_skill VALUES(4,'interpréter un personnage','Compétence qui vise à être un personnage de manière crédible,  en intégrant l''objectif, les obstacles et les actions du personnage.');
