PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "skills_activity" ("id_activity" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "activity_title" varchar(100) NOT NULL UNIQUE, "activity_description" text NOT NULL, "skill_id" integer NULL REFERENCES "skills_skill" ("id_skill") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "skills_skill" ("id_skill" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "skill_name" varchar(100) NOT NULL UNIQUE, "skill_description" text NOT NULL);
CREATE TABLE IF NOT EXISTS "skills_customuser" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "phone" varchar(20) NOT NULL, "bio" text NOT NULL);
CREATE TABLE IF NOT EXISTS "skills_customuser_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "customuser_id" bigint NOT NULL REFERENCES "skills_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "skills_customuser_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "customuser_id" bigint NOT NULL REFERENCES "skills_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "skills_customuser_skills" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "customuser_id" bigint NOT NULL REFERENCES "skills_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "skill_id" integer NOT NULL REFERENCES "skills_skill" ("id_skill") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "skills_assistance" ("id_assistance" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "assistance_type" varchar(16) NOT NULL, "assistance_status" varchar(16) NOT NULL, "start_date_time" datetime NOT NULL, "end_date_time" datetime NOT NULL, "creationDateTime" datetime NOT NULL, "activity_id" integer NOT NULL REFERENCES "skills_activity" ("id_activity") DEFERRABLE INITIALLY DEFERRED, "author_id" bigint NULL REFERENCES "skills_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "skills_appointment" ("id_appointment_activity" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "is_confirmed" bool NOT NULL, "isConfirmedByOfferer" bool NOT NULL, "confirmationDateTime" datetime NULL, "partner_id" bigint NULL REFERENCES "skills_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "assistance_id" integer NOT NULL REFERENCES "skills_assistance" ("id_assistance") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "skills_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
